  const rows = await helpers.httpRequest({ method:'GET', url: SB + '/googlenews?select=url,post_weight&post_weight=not.is.null', headers: { apikey: SRK, Authorization: 'Bearer ' + SRK }, json: true });
  for (const r of (rows || [])) { if (r && r.url) scored.add(String(r.url)); }
} catch (e) { return items; }
