// Parse News Prefilter — fail-open relevance filter.
// Reads the LLM JSON array [{url, relevant}], keeps only original articles
// (from "News New-Articles Only") whose url is marked relevant=true.
// On ANY error / parse failure, returns ALL original articles unchanged.
function llmText(j){
  if (j && Array.isArray(j.output)) { for (const mm of j.output) { if (mm && Array.isArray(mm.content)) { for (const c of mm.content) { if (c && typeof c.text === 'string') return c.text; } } } }
  if (j && typeof j.text === 'string') return j.text;
  if (j && typeof j.content === 'string') return j.content;
  if (j && j.message && typeof j.message.content === 'string') return j.message.content;
  if (j && Array.isArray(j.choices) && j.choices[0]) { const ch = j.choices[0]; if (ch.message && (ch.message.content || ch.message.reasoning)) return ch.message.content || ch.message.reasoning; if (typeof ch.text === 'string') return ch.text; }
  return '';
}
const original = $('News New-Articles Only').all();
try {
  const relevant = new Set();
  let sawAny = false;
  for (const item of $input.all()) {
    let raw = String(llmText(item.json) || '').replace(/```json/gi, '').replace(/```/g, '').trim();
    if (!raw) continue;
    const a = raw.indexOf('['); const b = raw.lastIndexOf(']');
    const txt = (a !== -1 && b !== -1 && b > a) ? raw.slice(a, b + 1) : raw;
    let parsed;
    try { parsed = JSON.parse(txt); } catch (e) { continue; }
    const arr = Array.isArray(parsed) ? parsed : [parsed];
    for (const e of arr) {
      if (e && e.url && e.relevant === true) { relevant.add(String(e.url)); }
      sawAny = true;
    }
  }
  // If the LLM produced nothing usable, fail open: keep everything.
  if (!sawAny) return original;
  const out = [];
  for (const it of original) {
    const u = String((it.json && it.json.url) || '');
    if (u && relevant.has(u)) out.push(it);
  }
  // Never drop everything: if filter would empty the batch, fail open.
  if (out.length === 0) return original;
  return out;
} catch (e) {
  return original;
}

const articles = $("Apify Google News (task)").all().map(i=>i.json);
const byUrl = {};
function norm(u){ if(!u) return ""; let s=String(u).trim(); s=s.replace(/[#?].*$/,""); s=s.replace(/\/+$/,""); return s.toLowerCase(); }
for (const a of articles) { const k = norm(a.url); if (k && !(k in byUrl)) byUrl[k] = a; }
