// Pair each attribution response back to its SOURCE article, flatten the
// multi-company schema, and emit exactly one item per article.
//
// Why this exists (2026-08-05): the 2026-07-23 multi-company refactor changed
// the gate's output to { url, companies:[{companyName,sentiment,reasoning}] },
// but everything downstream (the relevance gate, the post_weight writer) reads
// FLAT $json.companyName — so from Jul 20 on, nothing was ever written. The
// model also answers a bare "[]" for articles matching no company, which
// carries no url, so those rows couldn't even be resolved back to an article.
// Fixing both here keeps the change confined to this node.
const src = $('Update News articleText').all().map(i => i.json);
function llmText(j){
  if (j && Array.isArray(j.output)) { for (const mm of j.output) { if (mm && Array.isArray(mm.content)) { for (const c of mm.content) { if (c && typeof c.text === 'string') return c.text; } } } }
  if (j && typeof j.text === 'string') return j.text;
  if (j && typeof j.content === 'string') return j.content;
  if (j && j.message && typeof j.message.content === 'string') return j.message.content;
  if (j && Array.isArray(j.choices) && j.choices[0]) { const ch = j.choices[0]; if (ch.message && (ch.message.content || ch.message.reasoning)) return ch.message.content || ch.message.reasoning; if (typeof ch.text === 'string') return ch.text; }
  return '';
}
function srcIndexOf(item, i){
  const pi = item.pairedItem;
  if (pi == null) return i;
  if (typeof pi === 'number') return pi;
  if (Array.isArray(pi)) return (pi[0] && typeof pi[0].item === 'number') ? pi[0].item : i;
  return (typeof pi.item === 'number') ? pi.item : i;
}
const inputs = $input.all();
const results = [];
for (let i = 0; i < inputs.length; i++) {
  const item = inputs[i];
  const article = src[srcIndexOf(item, i)] || {};
  let raw = String(llmText(item.json) || '').replace(/```json/gi, '').replace(/```/g, '').trim();
  let parsed = null;
  if (raw) {
    const a = raw.indexOf('['), b = raw.lastIndexOf(']');
    const c = raw.indexOf('{'), d = raw.lastIndexOf('}');
    let txt = raw;
    if (a !== -1 && b > a) txt = raw.slice(a, b + 1);
    else if (c !== -1 && d > c) txt = raw.slice(c, d + 1);
    try { parsed = JSON.parse(txt); } catch (e) { parsed = null; }
  }
  // The response is normally a 1-element array; match on url when several come back.
  let el = null;
  if (Array.isArray(parsed)) el = parsed.find(x => x && x.url && article.url && x.url === article.url) || parsed[0] || null;
  else if (parsed && typeof parsed === 'object') el = parsed;
  // New schema: companies[]. Legacy flat companyName still accepted.
  let comps = [];
  if (el) {
    if (Array.isArray(el.companies)) comps = el.companies.filter(x => x && x.companyName && String(x.companyName).toUpperCase() !== 'NONE');
    else if (el.companyName && String(el.companyName).toUpperCase() !== 'NONE') comps = [{ companyName: el.companyName, sentiment: el.sentiment, reasoning: el.reasoning }];
  }
  const primary = comps[0] || null;
  // A bare "[]" is a VALID verdict (no company anchored) — distinct from an
  // unparseable reply, which must not be recorded as a clean NONE.
  const understood = parsed !== null;
  const out = Object.assign({}, article);
  delete out.articleText;   // keep the item light; nothing downstream needs it
  out.url = article.url || (el && el.url) || null;
  out.companyName = primary ? primary.companyName : 'NONE';
  // Pass the FULL list through: 'Compute News post_weight' rebuilds
  // company_names from `companies`, which is what makes a multi-company
  // article count for every company it names (2026-07-23 policy). Emitting
  // only the primary here would silently collapse that back to one.
  out.companies = comps;
  out.company_names = comps.map(x => ({ name: x.companyName, sentiment: x.sentiment != null ? x.sentiment : null, reasoning: x.reasoning || '' }));
  out.sentiment = (primary && primary.sentiment != null) ? primary.sentiment : null;
  out.reasoning = primary ? (primary.reasoning || '')
    : (understood ? 'no listed company anchored in this article' : 'attribution response unparseable');
  out.attribution_ok = understood;
  results.push({ json: out });
}
return results;

const results = [];
for (const item of $input.all()) { const j = item.json || {}; let raw = (typeof j.content === 'string' ? j.content : null) ?? j.output_text ?? j.text ?? (j.message && j.message.content) ?? (j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content) ?? ''; if (typeof raw !== 'string') raw = JSON.stringify(raw); raw = raw.replace(/```json|```/g, '').trim(); const m = raw.match(/\[[\s\S]*\]/); const txt = m ? m[0] : raw; let parsed; try { parsed = JSON.parse(txt); } catch (e) { continue; } const arr = Array.isArray(parsed) ? parsed : [parsed]; for (const e of arr) results.push({ json: e }); }
return results;

const ctx = $("Build Context").first().json; const cfg = ctx.config || {};
const clamp = cfg.sentimentClamp || { min:0.5, max:1.3 };
const halfLife = (cfg.halfLifeDays && cfg.halfLifeDays["Google News"]) || 30;
function newsTierMult(u){const nt=cfg.newsTiers;if(!nt||!nt.tiers)return 1;const m=String(u||'').match(/^[a-z][a-z0-9+.-]*:\/\/([^\/?#]+)/i);let host=m?m[1].replace(/^www\./i,'').toLowerCase():'';if(!host)return (nt.default!=null?nt.default:1);for(const k in nt.tiers){const t=nt.tiers[k];const ds=(t&&t.domains)||[];for(let i=0;i<ds.length;i++){const d=ds[i];if(host===d||host.endsWith('.'+d))return t.mult;}}return (nt.default!=null?nt.default:1);}
function llmText(j){
  if (j && Array.isArray(j.output)) { for (const mm of j.output) { if (mm && Array.isArray(mm.content)) { for (const c of mm.content) { if (c && typeof c.text === 'string') return c.text; } } } }
  if (j && typeof j.text === 'string') return j.text;
  if (j && typeof j.content === 'string') return j.content;
  if (j && j.message && typeof j.message.content === 'string') return j.message.content;
  if (j && Array.isArray(j.choices) && j.choices[0]) { const ch = j.choices[0]; if (ch.message && ch.message.content) return ch.message.content; }
  return '';
}
const credByUrl = {};
for (const item of $input.all()) {
  let raw = String(llmText(item.json) || '').replace(/```json/gi, '').replace(/```/g, '').trim();
  if (!raw) continue;
  const a = raw.indexOf('['); const b = raw.lastIndexOf(']');
  if (a === -1 || b === -1 || b <= a) continue;
  let arr; try { arr = JSON.parse(raw.slice(a, b + 1)); } catch (e) { continue; }
  for (const e of (Array.isArray(arr) ? arr : [arr])) { if (e && e.url != null) credByUrl[e.url] = Number(e.credibility_score); }
}
const sentByUrl = {};
$("Parse News LLM").all().forEach(i => { sentByUrl[i.json.url] = i.json; });
const articles = $("Apify Google News (task)").all().map(i => i.json);
const results = [];
for (const url of Object.keys(sentByUrl)) {
  const sent = sentByUrl[url];
  const _co=(sent&&Array.isArray(sent.companies))?sent.companies:((sent&&sent.companyName)?[{companyName:sent.companyName,sentiment:sent.sentiment,reasoning:sent.reasoning}]:[]);
  sent.company_names=_co.filter(c=>c&&c.companyName&&c.companyName!=='NONE').map(c=>({name:c.companyName,sentiment:(c.sentiment!=null?c.sentiment:null),reasoning:c.reasoning||''}));
  const _p=sent.company_names.length?sent.company_names[0]:null;
  sent.companyName=_p?_p.name:'NONE'; sent.sentiment=_p?_p.sentiment:null; sent.reasoning=_p?_p.reasoning:'';
  const cs = credByUrl[url];
  const credScore = (cs != null && !isNaN(cs)) ? cs : 50;
  const authorityMult = credScore / 50;
  const s = Math.max(-3, Math.min(3, Number(sent.sentiment || 0)));
  const sentimentMult = clamp.min + ((s + 3) / 6) * (clamp.max - clamp.min);
  let ageDays = 0; const article = articles.find(a => a.url === url) || {};
  if (article.publishedAt) { const d = new Date(article.publishedAt); if (!isNaN(d)) ageDays = Math.max(0, (Date.now() - d.getTime()) / 86400000); }
  const timeDecay = Math.pow(2, -ageDays / halfLife);
  const tierMult = newsTierMult(url);
  const post_weight = tierMult * sentimentMult * timeDecay;
  results.push({ json: { url: url, companyName: sent.companyName, sentiment: sent.sentiment, reasoning: sent.reasoning, credibility_score: credScore, post_weight: parseFloat(post_weight.toFixed(6)), company_names: sent.company_names } });
}
return results;
